SELECT id, dept_id, manager_id, job_title, salary, hire_date, is_remote, COUNT(salary) OVER (PARTITION BY job_title) AS job_title_count_salary, AVG(salary) OVER w_grp AS salary_avg_2, NTILE(3) OVER w_grp_2 AS salary_bucket FROM employees WHERE level IS NOT NULL WINDOW w_grp AS (PARTITION BY YEAR(hire_date), manager_id ORDER BY hire_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY job_title ORDER BY salary, id)
